const user = $json["message"]["from"];
return [{
    user_id: user.id,
    first_name: user.first_name,
    last_name: user.last_name || null,
    username: user.username || null,
    language_code: user.language_code || null,
    is_active: true,
    user_group: null  // có thể cập nhật sau thủ công
}];

const msg = $json["message"];

// Lấy các giá trị cần thiết
const chat_id = msg.chat.id;
const message_id = msg.message_id;
const user_id = msg.from.id;

// Safely get thread_id - kiểm tra xem reply_to_message có tồn tại không
const thread_id = msg.reply_to_message?.message_thread_id || msg.message_thread_id || null;

// Tạo custom_id bằng cách ghép chat_id, "00" và message_id
const custom_id = BigInt(chat_id.toString() + "00" + message_id.toString());

// Tạo topic_chat_id - chỉ tạo khi có thread_id
const topic_chat_id = thread_id ? BigInt(chat_id.toString() + thread_id.toString()) : null;

return [{
    message_id: message_id,
    chat_id: chat_id,
    topic_chat_id: topic_chat_id,
    user_id: user_id,
    custom_id: custom_id,
    date: new Date(msg.date * 1000),
    message_text: msg.text || null,
    entities: msg.entities ? JSON.stringify(msg.entities) : null,
    caption: msg.caption || null,
    photo: msg.photo ? JSON.stringify(msg.photo) : null,
    audio: msg.audio ? JSON.stringify(msg.audio) : null,
    document: msg.document ? JSON.stringify(msg.document) : null,
    sticker: msg.sticker ? JSON.stringify(msg.sticker) : null,
    video: msg.video ? JSON.stringify(msg.video) : null,
    voice: msg.voice ? JSON.stringify(msg.voice) : null,
    location: msg.location ? JSON.stringify(msg.location) : null,
    venue: msg.venue ? JSON.stringify(msg.venue) : null,
    message_thread_id: msg.message_thread_id || null,
    thread_reply_count: msg.thread ? msg.thread.reply_count : null,
    thread_top_message_id: msg.thread ? msg.thread.top_message_id : null
}];

